// AWI: sinkron kalkulator tahap 2 - sekali jalan (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/calcfix2', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$t = $wpdb->prefix . 'snippets';
			$nl = chr(92) . 'n';
			$a = "'" . $nl . "- Harga OTR: '+rp(otr)+'" . $nl . "- DP '+dpPct+'%: '+rp(r.dp)+'";
			$b = "'" . $nl . "- Harga OTR: '+(otr?rp(otr):'menunggu harga resmi (inden)')+'" . $nl . "- DP '+dpPct+'%: '+rp(r.dp)+'";
			$c = $wpdb->get_var("SELECT code FROM $t WHERE id=13");
			$n = substr_count($c, $a);
			if ($n) { $wpdb->update($t, array('code' => str_replace($a, $b, $c)), array('id' => 13)); }
			$bs = chr(92);
			if (function_exists('Code_Snippets' . $bs . 'clean_snippets_cache')) call_user_func('Code_Snippets' . $bs . 'clean_snippets_cache', $t);
			wp_cache_flush();
			return array('s13msg' => $n);
		},
	));
});
